package com.mo.economy_system.common.transfer;
import com.mo.economy_system.common.check.ClientFileCheckType;import com.mo.economy_system.common.network.EconomyNetworkLimits;import java.io.*;import java.nio.ByteBuffer;import java.nio.channels.*;import java.nio.file.*;import java.nio.file.attribute.*;import java.security.*;import java.util.*;
/** Copies one authenticated direct child to a private CREATE_NEW snapshot while hashing it. */
public final class CheckedFileSnapshotter{public record Snapshot(Path path,long size,String sha256) implements AutoCloseable{public void close()throws IOException{Files.deleteIfExists(path);}}public record Outcome(Snapshot snapshot,String errorCode){public boolean success(){return snapshot!=null;}}private static final Set<OpenOption> READ=Set.of(StandardOpenOption.READ,LinkOption.NOFOLLOW_LINKS);private CheckedFileSnapshotter(){}
 public static Outcome create(Path game,ClientFileCheckType type,String rawName,long expectedSize,String expectedHash,Path privateTemp,long deadlineNanos){String name;try{name=CheckedFileTransferValidation.fileName(rawName);CheckedFileTransferValidation.sha256(expectedHash);}catch(RuntimeException e){return new Outcome(null,"FILE_NOT_IN_CHECK_RESULT");}Path root=game.toAbsolutePath().normalize().resolve(type.id());try{BasicFileAttributes before=Files.readAttributes(root,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);if(!before.isDirectory()||before.isSymbolicLink()||before.fileKey()==null)return new Outcome(null,"DIRECTORY_PROVIDER_UNSAFE");try(DirectoryStream<Path> ds=Files.newDirectoryStream(root)){if(!(ds instanceof SecureDirectoryStream<Path> secure))return new Outcome(null,"DIRECTORY_PROVIDER_UNSAFE");BasicFileAttributeView self=secure.getFileAttributeView(BasicFileAttributeView.class);if(self==null||!Objects.equals(before.fileKey(),self.readAttributes().fileKey()))return new Outcome(null,"DIRECTORY_CHANGED");Files.createDirectories(privateTemp);Path temp=privateTemp.resolve(UUID.randomUUID()+".part");long count=0;MessageDigest digest=MessageDigest.getInstance("SHA-256");try(SeekableByteChannel in=secure.newByteChannel(Path.of(name),READ);SeekableByteChannel out=Files.newByteChannel(temp,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){long declared=in.size();if(declared>EconomyNetworkLimits.MAX_TRANSFER_FILE_BYTES)return fail(temp,"FILE_TOO_LARGE");ByteBuffer buffer=ByteBuffer.allocate(8192);while(true){if(Thread.currentThread().isInterrupted()||System.nanoTime()>=deadlineNanos)return fail(temp,"SNAPSHOT_FAILED");buffer.clear();int n=in.read(buffer);if(n<0)break;if(n==0)continue;count+=n;if(count>EconomyNetworkLimits.MAX_TRANSFER_FILE_BYTES)return fail(temp,"FILE_TOO_LARGE");digest.update(buffer.array(),0,n);buffer.flip();while(buffer.hasRemaining())out.write(buffer);}if(count!=declared||count!=in.size())return fail(temp,"FILE_CHANGED_RECHECK_REQUIRED");String hash=HexFormat.of().formatHex(digest.digest());if(count!=expectedSize||!hash.equals(expectedHash))return fail(temp,"FILE_CHANGED_RECHECK_REQUIRED");return new Outcome(new Snapshot(temp,count,hash),null);}catch(Throwable failure){Files.deleteIfExists(temp);if(failure instanceof Error e)throw e;return new Outcome(null,"SNAPSHOT_FAILED");}}}catch(IOException|NoSuchAlgorithmException|SecurityException e){return new Outcome(null,"SNAPSHOT_FAILED");}}
 private static Outcome fail(Path path,String code)throws IOException{Files.deleteIfExists(path);return new Outcome(null,code);}}
